INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-01-01', 'lesson-modals-b1-01', 1, 'sentence', 'I can swim.', 'Eu sei nadar.', '/aɪ kæn swɪm/', '"Can" = habilidade. Em português muitas vezes vira "saber".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-02', 'lesson-modals-b1-01', 2, 'sentence', 'She can speak three languages.', 'Ela fala três idiomas.', '/ʃiː kæn spiːk θriː ˈlæŋɡwɪdʒɪz/', 'Sem "s" e sem "to": "she can speak", nunca "she cans" ou "can to speak".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"languages","pos":"noun","ipa":"/ˈlæŋɡwɪdʒɪz/","gloss":"idiomas"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-03', 'lesson-modals-b1-01', 3, 'sentence', 'I can''t hear you.', 'Não estou te ouvindo.', '/aɪ kænt hɪr juː/', '"Can''t" com verbos de percepção (hear, see) = não conseguir agora.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-04', 'lesson-modals-b1-01', 4, 'sentence', 'Can I sit here?', 'Posso sentar aqui?', '/kæn aɪ sɪt hɪr/', '"Can I…?" = pedir permissão, informal.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"sit","pos":"verb","ipa":"/sɪt/","gloss":"sentar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-05', 'lesson-modals-b1-01', 5, 'sentence', 'Can you help me with this?', 'Pode me ajudar com isso?', '/kæn juː hɛlp miː wɪð ðɪs/', '"Can you…?" = pedido informal.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-06', 'lesson-modals-b1-01', 6, 'sentence', 'You can use my phone.', 'Pode usar meu celular.', '/juː kæn juːz maɪ foʊn/', '"You can" = dar permissão.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-07', 'lesson-modals-b1-01', 7, 'sentence', 'You can''t park here.', 'Não pode estacionar aqui.', '/juː kænt pɑːrk hɪr/', '"Can''t" = proibição por regra.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-08', 'lesson-modals-b1-01', 8, 'sentence', 'Can you see the sign?', 'Você consegue ver a placa?', '/kæn juː siː ðə saɪn/', 'Pergunta de capacidade.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sign","pos":"verb","ipa":"/saɪn/","gloss":"assinar"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-09', 'lesson-modals-b1-01', 9, 'sentence', 'It can get very cold at night.', 'Pode fazer muito frio à noite.', '/ɪt kæn ɡɛt ˈvɛri koʊld æt naɪt/', '"Can" = algo que às vezes acontece.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-01-10', 'lesson-modals-b1-01', 10, 'sentence', 'I will be able to help tomorrow.', 'Vou poder ajudar amanhã.', '/aɪ wɪl biː ˈeɪbəl tuː hɛlp təˈmɑːroʊ/', '"Can" não tem futuro: use "will be able to".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-02-01', 'lesson-modals-b1-02', 1, 'sentence', 'I could run fast when I was young.', 'Eu corria rápido quando era jovem.', '/aɪ kʊd rʌn fæst wɛn aɪ wɑːz jʌŋ/', '"Could" = habilidade no passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"fast","pos":"adverb","ipa":"/fæst/","gloss":"rápido"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"young","pos":"adjective","ipa":"/jʌŋ/","gloss":"jovem"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-02', 'lesson-modals-b1-02', 2, 'sentence', 'I couldn''t sleep last night.', 'Não consegui dormir ontem à noite.', '/aɪ ˈkʊdənt sliːp læst naɪt/', '"Couldn''t" = não conseguir no passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"couldn''t","pos":"verb","ipa":"/ˈkʊdənt/","gloss":"não podia (could not)"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-03', 'lesson-modals-b1-02', 3, 'sentence', 'Could you open the window?', 'Você poderia abrir a janela?', '/kʊd juː ˈoʊpən ðə ˈwɪndoʊ/', '"Could you…?" = pedido mais educado que "can you".', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","gloss":"janela"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-04', 'lesson-modals-b1-02', 4, 'sentence', 'Could I ask a question?', 'Eu poderia fazer uma pergunta?', '/kʊd aɪ æsk ə ˈkwɛstʃən/', 'Permissão formal.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-05', 'lesson-modals-b1-02', 5, 'sentence', 'It could rain later.', 'Pode chover mais tarde.', '/ɪt kʊd reɪn ˈleɪtər/', '"Could" = possibilidade.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-06', 'lesson-modals-b1-02', 6, 'sentence', 'We could go to the movies.', 'A gente podia ir ao cinema.', '/wiː kʊd ɡoʊ tuː ðə ˈmuːviz/', '"We could" = sugestão.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"movies","pos":"noun","ipa":"/ˈmuːviz/","gloss":"filmes"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-07', 'lesson-modals-b1-02', 7, 'sentence', 'You could try again tomorrow.', 'Você podia tentar de novo amanhã.', '/juː kʊd traɪ əˈɡɛn təˈmɑːroʊ/', 'Sugestão suave.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-08', 'lesson-modals-b1-02', 8, 'sentence', 'I was able to fix it in the end.', 'No fim, consegui consertar.', '/aɪ wɑːz ˈeɪbəl tuː fɪks ɪt ɪn ðə ɛnd/', 'Para um sucesso único no passado, prefira "was able to" a "could".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"fix","pos":"verb","ipa":"/fɪks/","gloss":"consertar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-09', 'lesson-modals-b1-02', 9, 'sentence', 'Could you speak up a little?', 'Pode falar um pouco mais alto?', '/kʊd juː spiːk ʌp ə ˈlɪtəl/', '"Speak up" = falar mais alto.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-02-10', 'lesson-modals-b1-02', 10, 'sentence', 'How could you forget?', 'Como você pôde esquecer?', '/haʊ kʊd juː fərˈɡɛt/', 'Surpresa ou reprovação.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"forget","pos":"verb","ipa":"/fərˈɡɛt/","gloss":"esquecer"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-03-01', 'lesson-modals-b1-03', 1, 'sentence', 'You should see a doctor.', 'Você deveria ir ao médico.', '/juː ʃʊd siː ə ˈdɑːktər/', '"Should" = conselho.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"doctor","pos":"noun","ipa":"/ˈdɑːktər/","gloss":"médico"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-02', 'lesson-modals-b1-03', 2, 'sentence', 'You shouldn''t eat so late.', 'Você não deveria comer tão tarde.', '/juː ˈʃʊdənt iːt soʊ leɪt/', 'Negativa: "shouldn''t" + verbo.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"shouldn''t","pos":"verb","ipa":"/ˈʃʊdənt/","gloss":"não deveria (should not)"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-03', 'lesson-modals-b1-03', 3, 'sentence', 'What should I do?', 'O que eu devo fazer?', '/wʌt ʃʊd aɪ duː/', 'Pedir conselho.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-04', 'lesson-modals-b1-03', 4, 'sentence', 'Should I call her?', 'Devo ligar para ela?', '/ʃʊd aɪ kɔːl hɜːr/', 'Pergunta com inversão: should + sujeito.', '[]'::jsonb, '[{"surface":"Should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-05', 'lesson-modals-b1-03', 5, 'sentence', 'The package should arrive today.', 'O pacote deve chegar hoje.', '/ðə ˈpækɪdʒ ʃʊd əˈraɪv təˈdeɪ/', '"Should" = expectativa, o normal é que aconteça.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-06', 'lesson-modals-b1-03', 6, 'sentence', 'It should be easy.', 'Deve ser fácil.', '/ɪt ʃʊd biː ˈiːzi/', 'Expectativa sobre algo.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"easy","pos":"adjective","ipa":"/ˈiːzi/","gloss":"fácil, tranquilo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-07', 'lesson-modals-b1-03', 7, 'sentence', 'I think we should leave now.', 'Acho que a gente devia ir embora agora.', '/aɪ θɪŋk wiː ʃʊd liːv naʊ/', '"I think we should" = sugestão com opinião.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-08', 'lesson-modals-b1-03', 8, 'sentence', 'I don''t think you should go.', 'Acho que você não deveria ir.', '/aɪ doʊnt θɪŋk juː ʃʊd ɡoʊ/', 'Em inglês a negação fica em "don''t think", não em "should".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-09', 'lesson-modals-b1-03', 9, 'sentence', 'You should have told me.', 'Você deveria ter me contado.', '/juː ʃʊd hæv toʊld miː/', '"Should have" + particípio = crítica sobre o passado.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-03-10', 'lesson-modals-b1-03', 10, 'sentence', 'You ought to rest.', 'Você devia descansar.', '/juː ɔːt tuː rɛst/', '"Ought to" = "should", um pouco mais formal.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ought","pos":"verb","ipa":"/ɔːt/","gloss":"deveria (ought to)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rest","pos":"verb","ipa":"/rɛst/","gloss":"descansar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-04-01', 'lesson-modals-b1-04', 1, 'sentence', 'I must finish this today.', 'Preciso terminar isso hoje.', '/aɪ mʌst ˈfɪnɪʃ ðɪs təˈdeɪ/', '"Must" = obrigação que vem de quem fala.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"finish","pos":"verb","ipa":"/ˈfɪnɪʃ/","gloss":"terminar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-02', 'lesson-modals-b1-04', 2, 'sentence', 'You must wear a seatbelt.', 'É obrigatório usar cinto.', '/juː mʌst wɛr ə ˈsiːtbɛlt/', 'Regra escrita ou ordem forte.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"wear","pos":"verb","ipa":"/wɛr/","gloss":"usar, vestir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"seatbelt","pos":"noun","ipa":"/ˈsiːtbɛlt/","gloss":"cinto de segurança"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-03', 'lesson-modals-b1-04', 3, 'sentence', 'You mustn''t smoke here.', 'É proibido fumar aqui.', '/juː ˈmʌsənt smoʊk hɪr/', '"Mustn''t" = proibido. Não é "não precisa".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mustn''t","pos":"verb","ipa":"/ˈmʌsənt/","gloss":"não pode (must not)"},{"surface":"smoke","pos":"verb","ipa":"/smoʊk/","gloss":"fumar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-04', 'lesson-modals-b1-04', 4, 'sentence', 'Passengers must show their tickets.', 'Os passageiros devem mostrar a passagem.', '/ˈpæsɪndʒərz mʌst ʃoʊ ðɛr ˈtɪkɪts/', 'Tom de aviso oficial.', '[]'::jsonb, '[{"surface":"Passengers","pos":"noun","ipa":"/ˈpæsɪndʒərz/","gloss":"passageiros"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"tickets","pos":"noun","ipa":"/ˈtɪkɪts/","gloss":"ingressos"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-05', 'lesson-modals-b1-04', 5, 'sentence', 'You must try this cake!', 'Você tem que provar este bolo!', '/juː mʌst traɪ ðɪs keɪk/', 'Recomendação entusiasmada.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"cake","pos":"noun","ipa":"/keɪk/","gloss":"bolo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-06', 'lesson-modals-b1-04', 6, 'sentence', 'She must be at work.', 'Ela deve estar no trabalho.', '/ʃiː mʌst biː æt wɜːrk/', '"Must" de dedução: quase certeza.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-07', 'lesson-modals-b1-04', 7, 'sentence', 'You must be tired after the trip.', 'Você deve estar cansado depois da viagem.', '/juː mʌst biː ˈtaɪərd ˈæftər ðə trɪp/', 'Dedução gentil.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-08', 'lesson-modals-b1-04', 8, 'sentence', 'It must have cost a lot.', 'Deve ter custado caro.', '/ɪt mʌst hæv kɔːst ə lɑːt/', '"Must have" + particípio = dedução sobre o passado.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-09', 'lesson-modals-b1-04', 9, 'sentence', 'I must admit I was wrong.', 'Tenho que admitir que estava errado.', '/aɪ mʌst ədˈmɪt aɪ wɑːz rɔːŋ/', 'Expressão fixa: "I must admit".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"admit","pos":"verb","ipa":"/ədˈmɪt/","gloss":"admitir"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-04-10', 'lesson-modals-b1-04', 10, 'sentence', 'Must we leave so early?', 'Temos mesmo que sair tão cedo?', '/mʌst wiː liːv soʊ ˈɜːrli/', 'Pergunta com "must" soa formal; na fala use "do we have to".', '[]'::jsonb, '[{"surface":"Must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-05-01', 'lesson-modals-b1-05', 1, 'sentence', 'I might go to the party.', 'Talvez eu vá à festa.', '/aɪ maɪt ɡoʊ tuː ðə ˈpɑːrti/', '"Might" = talvez. Em português usamos "talvez" + subjuntivo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-02', 'lesson-modals-b1-05', 2, 'sentence', 'It might rain this afternoon.', 'Pode ser que chova esta tarde.', '/ɪt maɪt reɪn ðɪs ˌæftərˈnuːn/', 'Possibilidade sem certeza.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"afternoon","pos":"noun","ipa":"/ˌæftərˈnuːn/","gloss":"tarde"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-03', 'lesson-modals-b1-05', 3, 'sentence', 'She might not come.', 'Pode ser que ela não venha.', '/ʃiː maɪt nɑːt kʌm/', '"Might not" = talvez não.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-04', 'lesson-modals-b1-05', 4, 'sentence', 'Take an umbrella. You might need it.', 'Leve um guarda-chuva. Talvez você precise.', '/teɪk ən ʌmˈbrɛlə juː maɪt niːd ɪt/', 'Conselho com possibilidade.', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"umbrella","pos":"noun","ipa":"/ʌmˈbrɛlə/","gloss":"guarda-chuva"},{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-05', 'lesson-modals-b1-05', 5, 'sentence', 'He might be sleeping.', 'Ele pode estar dormindo.', '/hiː maɪt biː ˈsliːpɪŋ/', 'Might + be + -ing = possibilidade sobre agora.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"sleeping","pos":"verb","ipa":"/ˈsliːpɪŋ/","gloss":"dormindo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-06', 'lesson-modals-b1-05', 6, 'sentence', 'They might have left already.', 'Pode ser que já tenham ido embora.', '/ðeɪ maɪt hæv lɛft ɔːlˈrɛdi/', '"Might have" + particípio = possibilidade no passado.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-07', 'lesson-modals-b1-05', 7, 'sentence', 'You might want to check that again.', 'Talvez seja bom conferir isso de novo.', '/juː maɪt wɑːnt tuː tʃɛk ðæt əˈɡɛn/', '"You might want to" = sugestão educada.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-08', 'lesson-modals-b1-05', 8, 'sentence', 'I might as well stay home.', 'Então é melhor eu ficar em casa.', '/aɪ maɪt æz wɛl steɪ hoʊm/', '"Might as well" = já que não tem opção melhor.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-09', 'lesson-modals-b1-05', 9, 'sentence', 'This might be the best pizza in town.', 'Esta talvez seja a melhor pizza da cidade.', '/ðɪs maɪt biː ðə bɛst ˈpiːtsə ɪn taʊn/', 'Opinião cautelosa.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"pizza","pos":"noun","ipa":"/ˈpiːtsə/","gloss":"pizza"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-05-10', 'lesson-modals-b1-05', 10, 'sentence', 'Might I suggest something?', 'Posso sugerir algo?', '/maɪt aɪ səɡˈdʒɛst ˈsʌmθɪŋ/', '"Might I" é muito formal, quase antiquado.', '[]'::jsonb, '[{"surface":"Might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"suggest","pos":"verb","ipa":"/səɡˈdʒɛst/","gloss":"sugerir"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-06-01', 'lesson-modals-b1-06', 1, 'sentence', 'Would you like some coffee?', 'Você aceita um café?', '/wʊd juː laɪk sʌm ˈkɔːfi/', '"Would you like" = oferecer com educação.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-02', 'lesson-modals-b1-06', 2, 'sentence', 'I''d like a glass of water.', 'Eu queria um copo de água.', '/aɪd laɪk ə ɡlæs ʌv ˈwɔːtər/', '"I''d like" = "I would like", pedido educado. Mais gentil que "I want".', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"glass","pos":"noun","ipa":"/ɡlæs/","gloss":"taça, copo"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-03', 'lesson-modals-b1-06', 3, 'sentence', 'Would you mind waiting?', 'Você se importa de esperar?', '/wʊd juː maɪnd ˈweɪtɪŋ/', '"Would you mind" + -ing = pedido muito educado.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mind","pos":"verb","ipa":"/maɪnd/","gloss":"se importar"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-04', 'lesson-modals-b1-06', 4, 'sentence', 'I would help you, but I am busy.', 'Eu te ajudaria, mas estou ocupado.', '/aɪ wʊd hɛlp juː bʌt aɪ æm ˈbɪzi/', 'Hipótese: o que faria em outra situação.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-05', 'lesson-modals-b1-06', 5, 'sentence', 'What would you do?', 'O que você faria?', '/wʌt wʊd juː duː/', 'Pergunta hipotética.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-06', 'lesson-modals-b1-06', 6, 'sentence', 'I''d rather stay here.', 'Prefiro ficar aqui.', '/aɪd ˈræðər steɪ hɪr/', '"I''d rather" + verbo = preferência.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"rather","pos":"adverb","ipa":"/ˈræðər/","gloss":"de preferência"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-07', 'lesson-modals-b1-06', 7, 'sentence', 'When I was a kid, we would play outside all day.', 'Quando eu era criança, a gente brincava lá fora o dia todo.', '/wɛn aɪ wɑːz ə kɪd wiː wʊd pleɪ ˌaʊtˈsaɪd ɔːl deɪ/', '"Would" = hábito no passado, como o imperfeito ("brincava").', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"kid","pos":"noun","ipa":"/kɪd/","gloss":"criança"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-08', 'lesson-modals-b1-06', 8, 'sentence', 'He said he would call.', 'Ele disse que ia ligar.', '/hiː sɛd hiː wʊd kɔːl/', '"Would" no discurso indireto de "will".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-09', 'lesson-modals-b1-06', 9, 'sentence', 'She wouldn''t listen.', 'Ela não quis ouvir.', '/ʃiː ˈwʊdənt ˈlɪsən/', '"Wouldn''t" = recusou-se.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"listen","pos":"verb","ipa":"/ˈlɪsən/","gloss":"escutar"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-06-10', 'lesson-modals-b1-06', 10, 'sentence', 'It would be great to see you.', 'Seria ótimo te ver.', '/ɪt wʊd biː ɡreɪt tuː siː juː/', '"It would be" = seria.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-07-01', 'lesson-modals-b1-07', 1, 'sentence', 'I have to work tomorrow.', 'Tenho que trabalhar amanhã.', '/aɪ hæv tuː wɜːrk təˈmɑːroʊ/', '"Have to" = obrigação que vem de fora (regra, chefe).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-02', 'lesson-modals-b1-07', 2, 'sentence', 'She has to wear a uniform.', 'Ela tem que usar uniforme.', '/ʃiː hæz tuː wɛr ə ˈjuːnɪfɔːrm/', 'Terceira pessoa: "has to".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wear","pos":"verb","ipa":"/wɛr/","gloss":"usar, vestir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"uniform","pos":"noun","ipa":"/ˈjuːnɪfɔːrm/","gloss":"uniforme"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-03', 'lesson-modals-b1-07', 3, 'sentence', 'You don''t have to come.', 'Você não precisa vir.', '/juː doʊnt hæv tuː kʌm/', '"Don''t have to" = não é necessário. Muito diferente de "mustn''t".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-04', 'lesson-modals-b1-07', 4, 'sentence', 'Do I have to pay now?', 'Tenho que pagar agora?', '/duː aɪ hæv tuː peɪ naʊ/', 'Pergunta com "do".', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-05', 'lesson-modals-b1-07', 5, 'sentence', 'We had to wait an hour.', 'Tivemos que esperar uma hora.', '/wiː hæd tuː weɪt ən ˈaʊər/', 'Passado de "must" e "have to": "had to".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-06', 'lesson-modals-b1-07', 6, 'sentence', 'I will have to leave early.', 'Vou ter que sair cedo.', '/aɪ wɪl hæv tuː liːv ˈɜːrli/', 'Futuro: "will have to".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-07', 'lesson-modals-b1-07', 7, 'sentence', 'I''ve got to go.', 'Tenho que ir.', '/aɪv ɡɑːt tuː ɡoʊ/', '"Have got to" = "have to", informal. Na fala: "I gotta go".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-08', 'lesson-modals-b1-07', 8, 'sentence', 'You didn''t have to do that.', 'Você não precisava ter feito isso.', '/juː ˈdɪdənt hæv tuː duː ðæt/', 'Agradecimento: não era obrigação.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-09', 'lesson-modals-b1-07', 9, 'sentence', 'Does he have to work on Sundays?', 'Ele tem que trabalhar aos domingos?', '/dʌz hiː hæv tuː wɜːrk ɑːn ˈsʌndeɪz/', 'Terceira pessoa na pergunta: "does he have to".', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sundays","pos":"proper noun","ipa":"/ˈsʌndeɪz/","gloss":"domingos"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-07-10', 'lesson-modals-b1-07', 10, 'sentence', 'You need to sign here.', 'Você precisa assinar aqui.', '/juː niːd tuː saɪn hɪr/', '"Need to" = necessidade, muito usado no lugar de "have to".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"sign","pos":"verb","ipa":"/saɪn/","gloss":"assinar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-modals-b1-08-01', 'lesson-modals-b1-08', 1, 'sentence', 'May I come in?', 'Posso entrar?', '/meɪ aɪ kʌm ɪn/', '"May I" = pedir permissão com formalidade.', '[]'::jsonb, '[{"surface":"May","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-02', 'lesson-modals-b1-08', 2, 'sentence', 'May I help you?', 'Posso ajudar?', '/meɪ aɪ hɛlp juː/', 'Frase clássica de atendimento.', '[]'::jsonb, '[{"surface":"May","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-03', 'lesson-modals-b1-08', 3, 'sentence', 'You may leave now.', 'Pode sair agora.', '/juː meɪ liːv naʊ/', '"You may" = permissão formal, de professor ou chefe.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-04', 'lesson-modals-b1-08', 4, 'sentence', 'It may take a few days.', 'Pode levar alguns dias.', '/ɪt meɪ teɪk ə fjuː deɪz/', '"May" = possibilidade, tom neutro ou formal.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-05', 'lesson-modals-b1-08', 5, 'sentence', 'He may be right.', 'Talvez ele tenha razão.', '/hiː meɪ biː raɪt/', 'Possibilidade, como "might".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-06', 'lesson-modals-b1-08', 6, 'sentence', 'Visitors may not take photos.', 'Visitantes não podem tirar fotos.', '/ˈvɪzɪtərz meɪ nɑːt teɪk ˈfoʊtoʊz/', '"May not" em aviso = não é permitido.', '[]'::jsonb, '[{"surface":"Visitors","pos":"noun","ipa":"/ˈvɪzɪtərz/","gloss":"visitantes"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"photos","pos":"noun","ipa":"/ˈfoʊtoʊz/","gloss":"fotos"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-07', 'lesson-modals-b1-08', 7, 'sentence', 'I may not be able to come.', 'Talvez eu não consiga vir.', '/aɪ meɪ nɑːt biː ˈeɪbəl tuː kʌm/', '"May not" também = talvez não.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-08', 'lesson-modals-b1-08', 8, 'sentence', 'She may have missed the train.', 'Ela pode ter perdido o trem.', '/ʃiː meɪ hæv mɪst ðə treɪn/', '"May have" + particípio = possibilidade no passado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-09', 'lesson-modals-b1-08', 9, 'sentence', 'May I have the check, please?', 'Pode me trazer a conta, por favor?', '/meɪ aɪ hæv ðə tʃɛk pliːz/', 'Pedido educado no restaurante.', '[]'::jsonb, '[{"surface":"May","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-modals-b1-08-10', 'lesson-modals-b1-08', 10, 'sentence', 'May all your dreams come true.', 'Que todos os seus sonhos se realizem.', '/meɪ ɔːl jʊr driːmz kʌm truː/', '"May" no início = desejo, em votos e cartões.', '[]'::jsonb, '[{"surface":"May","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"dreams","pos":"noun","ipa":"/driːmz/","gloss":"sonhos"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"}]'::jsonb, NULL, NULL)
